import{esc,button,input,select,range}from'../phase4/ui.js';
import{frac,numeric,decimalPair,ftext}from'./b17-model.js';
const f=(k,l,v)=>input(k,l,v,'autocomplete="off" spellcheck="false"'),btn=(a,l,d='')=>button('b17-'+a,l,d),on=x=>`aria-pressed="${!!x}"`,choices=[['<','< 小于'],['=','= 等于'],['>','> 大于']],colors=['#c98550','#61958a','#a194bc','#c3a34e'];
const row=(n,d,color=0)=>`<div class="b17-fixedbar"><i style="width:${100*n/d}%;background:${colors[color]}"></i>${Array.from({length:Math.min(d,50)+1},(_,i)=>`<em style="left:${i*100/Math.min(d,50)}%"></em>`).join('')}</div>`;
const pieces=(d,count,selected,action,data='',wholes=Math.ceil(count/d))=>`<div class="b17-piecewrap" style="--den:${d};--wholes:${wholes}">${Array.from({length:Math.ceil(count/d)},(_,w)=>`<div class="b17-whole" aria-label="第${w+1}个整体">${Array.from({length:d},(_,k)=>{const i=w*d+k;if(action==='none')return `<span class="b17-staticpart ${selected.includes(i)?'filled':''}"></span>`;return btn(action,selected.includes(i)?'●':'',`data-index="${i}" ${data} ${on(selected.includes(i))} aria-label="第${i+1}小份"`);}).join('')}</div>`).join('')}</div>`;
const axes=(values,min=0,max=2)=>`<svg class="b17-line" viewBox="0 0 760 150" role="img" aria-label="同一单位的数轴"><path d="M40 90H720" stroke="#78654d" stroke-width="2"/>${Array.from({length:Math.ceil(max-min)+1},(_,i)=>`<path d="M${40+i/(max-min)*680} 83v15" stroke="#78654d"/><text x="${40+i/(max-min)*680}" y="125" text-anchor="middle">${min+i}</text>`).join('')}${values.map(([label,v],i)=>`<path d="M${40+(v-min)/(max-min)*680} 90V${65-i%3*19}" stroke="${colors[i%4]}"/><circle cx="${40+(v-min)/(max-min)*680}" cy="90" r="5" fill="${colors[i%4]}"/><text x="${40+(v-min)/(max-min)*680}" y="${59-i%3*19}" text-anchor="middle">${esc(label)}</text>`).join('')}</svg>`;
function order(t,m){const b=m.board;if(!b.committed)return`<div class="b17-cards">${t.cards.map((x,i)=>btn('card',x,`data-index="${i}" ${on(b.prediction.includes(i))}`)).join('')}</div><p class="b17-note">先猜${t.desc?'从大到小':'从小到大'}：${b.prediction.map(i=>esc(t.cards[i])).join(' → ')||'点卡片排一排'}</p>`;
 return`<div class="b17-orderbars">${t.cards.map((x,i)=>{const[n,d]=frac(x);return`<section style="${!b.aligned&&i===1?'max-width:50%':''}">${btn('select',x,`data-index="${i}" ${on(b.selected===i)}`)}${pieces(d,n,b.parts[i],'shade',`data-row="${i}"`,Math.max(...t.cards.map(x=>Math.ceil(numeric(x)))))}${b.common?`<div class="b17-renamed-parts"><small>同一个量，改用每份1/${b.common}</small>${pieces(b.common,n*b.common/d,b.parts[i].flatMap(k=>Array.from({length:b.common/d},(_,j)=>k*b.common/d+j)),'none','',Math.max(...t.cards.map(x=>Math.ceil(numeric(x)))))}${b.renames[i]?`<span>${esc(b.renames[i])}</span>`:''}</div>`:''}</section>`;}).join('')}</div>${axes(Object.entries(b.placements).map(([i,s])=>[t.cards[i],numeric(s)]),t.min||0,t.max||2)}<div class="b17-cards">${t.cards.map((x,i)=>btn('order',x,`data-index="${i}" ${on(b.ordered.includes(i))}`)).join('')}</div><p class="b17-note">${t.desc?'从大到小':'从小到大'}：${b.ordered.map(i=>esc(t.cards[i])).join(' → ')||'把卡片排到这里'}</p>`;}
function rename(t,m){const b=m.board;if(!b.opened)return`<div class="b17-number">${esc(t.decimalStart)}</div>`;return`<div class="b17-rename"><div>原来的量 ${t.n}/${t.d}</div>${row(t.n,t.d)}<div>现在分成 ${b.d} 份，选中 ${b.n} 份</div>${row(b.n,b.d,1)}${(b.d>50||t.d>50)?'<small>细分很多时，浅色保持原来的量；图上的分界仅作等距分组显示。</small>':''}${b.tested?`<div>若给原来的${t.n}/${t.d}上下各加1：${t.n+1}/${t.d+1}</div>${row(t.n+1,t.d+1,2)}`:''}<div class="b17-cards">${b.saved.map(r=>`<span>${ftext(r)}</span>`).join('')}</div></div>`;}
function compare(t,m){const b=m.board,p=decimalPair(t,b);if(!p)return'<div class="b17-done">这些量都比较过了。</div>';if(!b.predicted)return`<div class="b17-number">${p.raw[0]}　?　${p.raw[1]}</div>`;const lo=Math.floor(Math.min(...p.raw.map(Number))),span=Math.ceil(Math.max(...p.raw.map(Number)))-lo||1;return`<div class="b17-decimals">${p.raw.map((x,j)=>`<div><b>${b.padded?p.padded[j]:x}</b>${row((Number(x)-lo)/span,1,j)}</div>`).join('')}<small>两条都从 ${lo} 到 ${lo+span}，整体一样长</small>${b.padded?`<div class="b17-columns">${p.digits[0].map((_,i)=>btn('scan',`${p.digits[0][i]} / ${p.digits[1][i]}`,`data-index="${i}" ${on(b.scanned.includes(i))} aria-label="比较${i<p.width?'整数第'+(i+1)+'位':['十分位','百分位','千分位'][i-p.width]}"`)).join('')}</div>`:''}</div>`;}
function zoom(t,m){const b=m.board;return`<div class="b17-zoomtrail">${b.levels.map((n,i)=>`<span>第${i+1}次：放大第${n+1}段</span>`).join('')}</div><div class="b17-zoomends"><span>${b.lo/1000}</span><span>${(b.lo+b.span)/1000}</span></div><div class="b17-zoomstrip">${Array.from({length:10},(_,i)=>btn('zoom','',`data-index="${i}" aria-label="放大第${i+1}段" ${b.span<=10?'disabled':''}`)).join('')}</div><div class="b17-marks">${Array.from({length:11},(_,i)=>btn('mark','│',`data-index="${i}" ${on(b.mark===b.lo+b.span*i/10)} aria-label="放在从左数第${i}步"`)).join('')}</div>${b.mark!==null?`<p class="b17-note">你放在 ${b.mark/1000}</p>`:''}`;}
function hundred(t,m){const b=m.board;return`<div class="b17-hundred"><div class="b17-grid">${b.cells.map((v,i)=>btn('cell','',`data-index="${i}" style="background:${v<0?'#faf6ed':colors[v]}" aria-label="第${i+1}小格${v<0?'':v===0?'，第一部分':'，第二部分'}"`)).join('')}</div><div class="b17-tenbuttons">${Array.from({length:10},(_,i)=>btn('ten','↔',`data-index="${i}" aria-label="取或放回第${i+1}整行"`)).join('')}</div></div><div class="b17-cards">${btn('layer',`取 ${t.tenths}/10`,`data-index="0" ${on(b.layer===0)}`)}${btn('layer',`接 ${t.hundredths}/100`,`data-index="1" ${on(b.layer===1)}`)}</div>`;}
function decimalEngine(t,m){const b=m.board;return`<div class="b17-number">${t.n} ÷ ${t.d}</div>${b.simple?`<div class="b17-factors">${b.simple[0]}/${b.simple[1]}　整个的份数：${b.factors.join(' × ')}${b.factorLeft>1?(b.factors.length?' × ':'')+b.factorLeft:''}</div>`:''}${b.rows.length?`<table class="b17-division"><thead><tr><th>这一行的量</th><th>分出几份</th><th>余下多少</th></tr></thead><tbody>${b.rows.map((r,i)=>`<tr><td>${r.input} 个 ${i===0?'1':'1/'+10**i}</td><td>${i===0?'整数位：':'小数第'+i+'位：'}${r.q}</td><td>${r.rem} 个 ${i===0?'1':'1/'+10**i}</td></tr>`).join('')}</tbody></table>`:''}${b.stop?`<p class="b17-note">${b.cycle===null?'余下0，这次分完了。':'这个余数已经出现过，后面的分法会重复。'}</p>`:''}`;}
function operations(t,m){const b=m.board;const op={'+':'+','-':'−','*':'×','/':'÷'}[t.op];if(!b.prediction)return`<div class="b17-number">${esc(t.a)}　${op}　${esc(t.b)}</div>`;if(!b.forms)return`<div class="b17-number">${esc(t.a)}　${op}　${esc(t.b)}</div>`;const [aa,bb]=b.forms;
 if(t.op==='*'){const cols=Math.ceil(aa[0]/aa[1])*aa[1],rows=Math.ceil(bb[0]/bb[1])*bb[1];return`<div class="b17-product"><div class="b17-product-cols" style="--cols:${cols}">${Array.from({length:cols},(_,i)=>btn('column','↓',`data-index="${i}" ${on(b.columns.includes(i))} aria-label="取第${i+1}列"`)).join('')}</div><div class="b17-product-main"><div class="b17-product-rows">${Array.from({length:rows},(_,i)=>btn('row','→',`data-index="${i}" ${on(b.rows.includes(i))} aria-label="取第${i+1}行"`)).join('')}</div><div class="b17-product-grid" style="--cols:${cols}">${Array.from({length:rows*cols},(_,i)=>`<i style="background:${b.rows.includes(Math.floor(i/cols))&&b.columns.includes(i%cols)?colors[0]:b.rows.includes(Math.floor(i/cols))?'#dbe9e5':b.columns.includes(i%cols)?'#f2ddc5':'#faf6ed'};border-right-width:${i%aa[1]===aa[1]-1?3:1}px;border-bottom-width:${Math.floor(i/cols)%bb[1]===bb[1]-1?3:1}px"></i>`).join('')}</div></div><p>粗线围成的每一整格代表1；每整格里是 ${aa[1]} × ${bb[1]} 小格。</p></div>`;}
 if(!b.denom)return`<div class="b17-number">${ftext(aa)}　${op}　${ftext(bb)}</div>`;
 const A=aa[0]*b.denom/aa[1],B=bb[0]*b.denom/bb[1],wholeCount=Math.ceil(Math.max(A,B,t.op==='+'?A+B:A)/b.denom);return`<div class="b17-operation-bars"><span>${ftext(aa)}</span>${pieces(b.denom,A,b.left,'shade','data-row="left"',wholeCount)}<span>${ftext(bb)}</span>${pieces(b.denom,B,b.right,'shade','data-row="right"',wholeCount)}</div>${b.combined?`<div class="b17-result-parts">${t.op==='+'?'把两段接起来':'从第一段拿走第二段'}${pieces(b.denom,Math.max(1,t.op==='+'?A+B:A),Array.from({length:t.op==='+'?A+B:A-B},(_,i)=>i),'none','',wholeCount)}</div>`:''}${t.op==='/'?`<div class="b17-fit">${Array.from({length:b.fits},(_,i)=>`<span>第${i+1}组：${B}小份</span>`).join('')}${b.rest?`<span>还余 ${A-b.fits*B} 小份，每整组有 ${B} 小份</span>`:''}</div>`:''}`;}
function angle(t,m){const a=m.board.angle??(Number(m.angle)||0),p=d=>[340+200*Math.cos(d*Math.PI/180),240-200*Math.sin(d*Math.PI/180)],sector=(s,e)=>`M340,240 L${p(s)} A200,200 0 0 0 ${p(e)} Z`;return`<svg class="b17-angle" viewBox="0 0 700 300"><path d="${sector(0,t.known)}" fill="#e5b98c" stroke="#846a4e"/><path d="${sector(t.known,t.known+a)}" fill="#8eb8ae" fill-opacity=".7" stroke="#507f75"/><path d="M100 240H590" stroke="#57452e" stroke-width="3"/><text x="490" y="210">${t.known}°</text><text x="225" y="165">你补 ${a}°</text><text x="320" y="275">一条直线</text></svg>`;}
export function visual(t,m){const b=m.board;switch(t.type){case'x-fracorder':return order(t,m);case'x-fracrename':return rename(t,m);case'x-decimalcompare':return compare(t,m);case'x-decimalzoom':return zoom(t,m);case'x-hundredcombine':return hundred(t,m);case'x-complementpair':return`<div class="b17-joinline">${b.left!==null?`<i style="width:${50*numeric(b.left)}%">${esc(b.left)}</i><i style="width:${50*numeric(b.right)}%">${esc(b.right)}</i>`:''}<em></em></div><div class="b17-zoomends"><span>0</span><span>1</span><span>2</span></div>`;case'x-decimalengine':return decimalEngine(t,m);case'x-percentkit':return`<p class="b17-note">整体 ${t.total} 元</p>${row(1,1)}<div class="b17-percentparts">${b.pieces.map((n,i)=>`<i style="width:${n}%">${n}%</i>`).join('')}</div>${b.tenth!==null?`<p>你分出10%：${esc(b.tenth)}元${b.fifth!==null?'；再分出5%：'+esc(b.fifth)+'元':''}</p>`:''}`;case'x-rulejump':return`<div class="b17-number">${esc(t.context)}</div>${b.rule?`<p class="b17-rule">（输入 × ${b.rule[0]} ＋ ${b.rule[1]}）÷ ${b.rule[2]}</p>`:''}<div class="b17-cards">${b.records.map(r=>`<span>${r.n} → ${esc(r.result)}</span>`).join('')}</div>`;case'x-fracoperations':return operations(t,m);case'x-fdprecall':return b.index<t.cases.length?`<div class="b17-number">${ftext(t.cases[b.index])}</div>`:`<div class="b17-done">${b.records.map(r=>`${ftext(r.fraction)} = ${esc(r.decimal)} = ${esc(r.percent)}%`).join('<br>')}</div>`;case'x-straightgap':return angle(t,m);}}
export function controls(t,m){const b=m.board;switch(t.type){
 case'x-fracorder':if(!b.committed)return btn('predict','留下预测，再摆一摆');if(!b.aligned)return btn('align','先让两边的整体一样长');return f('position',`把 ${t.cards[b.selected]} 放在什么位置（可写分数）`,m.position)+btn('place','放到线上')+(t.common?f('denom','每个整体都细分成多少份',m.denom)+btn('common','画出共同小份')+(b.common?f('fraction',`给 ${t.cards[b.selected]} 换成新的分数名字`,m.fraction)+btn('rename','记录这个新名字'):''):'')+(t.gaps?f('answer',`${t.cards[b.selected]} 离1还差多少`,m.answer)+btn('landmark','留下这段距离'):'')+(t.benchmark?select('relation',`${t.cards[b.selected]} 与1/2相比`,m.relation,choices)+btn('landmark','留下这个位置关系'):'');
 case'x-fracrename':if(!b.opened)return f('fraction','先按最后一位的小份写成分数',m.fraction)+btn('open-decimal','把这个量展开');return f('factor','每份再分几份，或把几份合成一组',m.factor)+btn('split','每份都继续分')+btn('merge','每组都合起来')+btn('rewind','回到最初分法')+f('fraction','现在选中的量怎样写',m.fraction)+btn('remember','留下这个名字')+(t.testAdd?btn('test-add','试试上下各加1')+(b.tested?select('relation','加1后，量有没有变',m.relation,[['same','没变'],['changed','变了']]):''):'')+(b.saved.length?select('reason','刚才分或合时，什么保持不变',m.reason,[['recut','整个和选中的量都没变'],['top','只保证上面的数一样']])+(t.hcf?f('hcf','两边能一起除的最大整数是几',m.hcf):'')+(t.decimal?f('decimal','同一个量写成小数',m.decimal):''):'');
 case'x-decimalcompare':{const p=decimalPair(t,b);if(!p)return'';if(!b.predicted)return select('prediction','先猜左边与右边相比',m.prediction,choices)+btn('predict-compare','留下预测');return(!b.padded?f('left','左边补到相同小数位',m.left)+f('right','右边补到相同小数位',m.right)+btn('pad','让相同单位对齐'):select('relation','看过每列后，怎样比较',m.relation,choices)+btn('compare','留下比较，再换一对'));}
 case'x-decimalzoom':return f('fraction','这个量用千分之一写成分数',m.fraction)+f('decimal','同一个位置的小数',m.decimal)+f('answer','最细的一步占原来整个的多少',m.answer);
 case'x-hundredcombine':return f('left',`${t.tenths}/10 换成几/100`,m.left)+f('answer','接好后共有几/100',m.answer)+f('decimal','同一位置的小数',m.decimal);
 case'x-complementpair':return f('left',t.left?`第一段写 ${t.left}`:'自己选第一段（三位小数）',m.left)+f('right','第二段（三位小数）',m.right)+btn('pair','把两段接起来');
 case'x-decimalengine':if(!b.simple)return f('fraction','先写成最简分数（整数也可写几/1）',m.fraction)+btn('reduce','保留这个量，合并小份');if(b.factorLeft>1)return f('factor','剩下的份数还能除以哪个质数',m.factor)+btn('factor','拆出这个因子');if(!b.prediction)return select('kind','看这些因子，猜小数会怎样',m.kind,[['stop','会分完'],['repeat','会循环']])+btn('predict-stop','留下判断，再实际分');if(!b.stop){const n=b.rows.length?b.remainder*10:b.remainder;return`<span>${b.rows.length?'把余量换成更小的单位。':''}这一行：${n} 个 ${b.rows.length?'1/'+10**b.rows.length:'1'}，平均分给 ${b.simple[1]} 份</span>`+f('q','这一位分出几份',m.q)+f('remainder','余下多少',m.remainder)+btn('digit','留下这一行，继续分');}return select('kind','现在怎样判断',m.kind,[['stop','会分完'],['repeat','会循环']])+btn('predict-stop','记录判断')+f('answer',b.cycle===null?'写下精确的小数':'只写重复的那一段数字',m.answer)+select('reason','为什么这些因子能决定',m.reason,[['base-ten','10的质数因子只有2和5，重复余数会重复后续步骤'],['size','整个的份数大就会循环']]);
 case'x-percentkit':return b.tenth===null?f('amount','把整个分10份，一份多少元',m.amount)+btn('tenth','分出10%'):b.fifth===null?f('amount','把刚才的一份再平分，半份多少元',m.amount)+btn('fifth','再分出5%'):btn('piece','接一块10%','data-value="10"')+btn('piece','接一块5%','data-value="5"')+f('percent','这些块一共是百分之几',m.percent)+f('answer','拼出的量一共多少元',m.answer)+select('reason','换了总金额后，什么仍保持',m.reason,[['same-total','比例不变，每块金额跟着新整体变化'],['fixed','每块金额永远一样']]);
 case'x-rulejump':return f('multiplier','先乘几',m.multiplier)+f('offset','再加几（可用负数）',m.offset)+f('divisor','最后除以几',m.divisor)+btn('rule','照这样搭一条规则')+(b.rule?select('n','选一个输入试规则',m.n,t.inputs.map(n=>[n,String(n)]))+f('answer','你这条规则算出多少',m.answer)+btn('run','记录一次运行'):'');
 case'x-fracoperations':if(!b.prediction)return select('prediction','先估结果落在哪里',m.prediction,[['negative','比0小'],['zero','等于0'],['part','0与1之间'],['one','等于1'],['more','比1大']])+btn('predict-op','留下估计，再构造');if(!b.forms)return f('aform',`把 ${t.a} 全部写成分数`,m.aform)+f('bform',`把 ${t.b} 全部写成分数`,m.bform)+btn('forms','用这些小份表示原量');return(t.op!=='*'?f('denom','每个整体统一细分成多少小份',m.denom)+btn('common','分成同样小的份')+(b.denom?(t.op==='/'?btn('fit','放下一整组')+btn('rest','余下的相对一组看一看')+(b.rest?f('whole','放下几整组',m.whole)+f('part','还占一组的几分之几',m.part):''):btn('combine',t.op==='+'?'把两部分接起来':'从第一部分拿走第二部分')):''):'')+f('answer','构造得到的量是多少',m.answer)+select('reason','这次操作在做什么',m.reason,[['same-parts','同样小的份，接起来或拿走'],['scale','取一部分中的一部分'],['groups','看前面的量能装下几组后面的量']]);
 case'x-fdprecall':return b.index<t.cases.length?f('decimal','同一个量的小数',m.decimal)+f('percent','同一个量是百分之几',m.percent)+btn('recall','留下这两个名字'):'';
 case'x-straightgap':return range('angle','把补上的角调到几度',m.angle,0,180,1)+btn('angle','把这块放上去')+f('answer','缺的角是多少度',m.answer)+f('equation','不用测量，把角度关系写成等式',m.equation)+select('reason','用的是哪一条关系',m.reason,[['straight','同一直线上相邻的角合为180°'],['round','任何两个角都合为360°']]);
 }return'';}
export const render=(t,m)=>`<section class="b17-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p class="b17-issue" role="status">${esc(m.issue)}</p>`:''}${btn('reset','重新摆，保留之前的尝试')}</div></section>`;
